class Solution {
    public String getSmallestString(String s,int k){
        char[] letters=s.toCharArray();
        for(int index=0;index<letters.length&&k>0;index++){
            int direct=letters[index]-'a',distance=Math.min(direct,26-direct);
            if(distance<=k){
                letters[index]='a';
                k-=distance;
            }else{
                letters[index]=(char)(letters[index]-k);
                k=0;
            }
        }
        return new String(letters);
    }
}

code.kotlin:
class Solution {
    fun getSmallestString(s:String,k:Int):String{
        val letters=s.toCharArray();
        var remaining=k;
        for(index in letters.indices){
            if(remaining==0)break;
            val direct=letters[index]-'a';
            val distance=minOf(direct,26-direct);
            if(distance<=remaining){
                letters[index]='a';
                remaining-=distance
            }else{
                letters[index]=(letters[index].code-remaining).toChar();
                remaining=0
            }
        };
        return letters.concatToString()
    }
}

